<script setup lang="ts">
import { Form, Head, Link, router } from '@inertiajs/vue3'; import { computed, ref } from 'vue'; import { CreditCard, Pencil, Plus, Search, Trash2, X } from '@lucide/vue'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input'; import { Label } from '@/components/ui/label';
type Item={id:number;name:string;price:string|number;duration_days:number;description:string|null}; type LinkItem={url:string|null;label:string;active:boolean}; type Props={packages:{data:Item[];current_page:number;last_page:number;total:number;links:LinkItem[]};filters:{search:string};stats:{total:number}}; const props=defineProps<Props>(); const show=ref(false),editing=ref<Item|null>(null),key=ref(0),search=ref(props.filters.search??''); const title=computed(()=>editing.value?'Edit paket keanggotaan':'Tambah paket keanggotaan'),action=computed(()=>editing.value?`/membership-packages/${editing.value.id}`:'/membership-packages'),method=computed(()=>editing.value?'put':'post'); function openCreate(){editing.value=null;key.value++;show.value=true} function openEdit(x:Item){editing.value=x;key.value++;show.value=true} function close(){show.value=false;editing.value=null} function filter(){router.get('/membership-packages',{search:search.value||undefined},{preserveState:true,replace:true})} function reset(){search.value='';filter()} function remove(x:Item){if(confirm(`Hapus ${x.name}?`))router.delete(`/membership-packages/${x.id}`)} function money(v:string|number){return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(v))}
</script>
<template><Head title="Paket Keanggotaan"/><div class="space-y-6 p-4 md:p-6"><div class="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-sm font-medium text-primary">Data Master</p><h1 class="mt-1 text-2xl font-semibold tracking-tight">Paket Keanggotaan</h1><p class="mt-1 text-sm text-muted-foreground">Kelola paket keanggotaan gym.</p></div><Button @click="openCreate"><Plus class="mr-2 size-4"/> Tambah paket keanggotaan</Button></div><div class="rounded-2xl border bg-card p-4 shadow-sm"><div class="flex justify-between"><span class="text-sm text-muted-foreground">Total paket</span><CreditCard class="size-4 text-muted-foreground"/></div><div class="mt-3 text-2xl font-semibold">{{props.stats.total}}</div></div><div class="rounded-2xl border bg-card shadow-sm"><div class="flex gap-3 border-b p-4"><div class="relative flex-1"><Search class="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"/><Input v-model="search" @keyup.enter="filter" class="pl-9" placeholder="Cari paket keanggotaan..."/></div><Button variant="secondary" @click="filter">Filter</Button><Button variant="ghost" @click="reset">Reset</Button></div><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-muted/40 text-left text-xs uppercase tracking-wide text-muted-foreground"><tr><th class="px-5 py-3">Paket</th><th class="px-5 py-3">Harga</th><th class="px-5 py-3">Durasi</th><th class="px-5 py-3">Deskripsi</th><th class="px-5 py-3 text-right">Aksi</th></tr></thead><tbody class="divide-y"><tr v-for="x in props.packages.data" :key="x.id" class="hover:bg-muted/20"><td class="px-5 py-4 font-medium"><Link :href="`/membership-packages/${x.id}`" class="text-primary hover:underline">{{x.name}}</Link></td><td class="px-5 py-4 font-semibold">{{money(x.price)}}</td><td class="px-5 py-4">{{x.duration_days}} hari</td><td class="max-w-md px-5 py-4 text-muted-foreground">{{x.description||'—'}}</td><td class="px-5 py-4"><div class="flex justify-end gap-1"><Button variant="ghost" size="icon" title="Edit" @click="openEdit(x)"><Pencil class="size-4"/></Button><Button variant="ghost" size="icon" title="Hapus" @click="remove(x)"><Trash2 class="size-4 text-destructive"/></Button></div></td></tr><tr v-if="!props.packages.data.length"><td colspan="5" class="px-5 py-16 text-center">Paket keanggotaan tidak ditemukan</td></tr></tbody></table></div></div></div><div v-if="show" class="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"><div class="w-full max-w-lg rounded-2xl border bg-background shadow-2xl"><div class="flex justify-between border-b p-5"><div><p class="text-sm font-medium text-primary">Manajemen paket keanggotaan</p><h2 class="text-xl font-semibold">{{title}}</h2></div><Button variant="ghost" size="icon" @click="close"><X class="size-4"/></Button></div><Form :key="key" :action="action" :method="method" class="space-y-4 p-5" @success="close" v-slot="{errors,processing}"><div><Label>Nama</Label><Input name="name" :default-value="editing?.name" required/><p class="text-xs text-destructive">{{errors.name}}</p></div><div><Label>Harga</Label><Input name="price" type="number" min="0" :default-value="editing?.price" required/></div><div><Label>Durasi (hari)</Label><Input name="duration_days" type="number" min="1" :default-value="editing?.duration_days" required/></div><div><Label>Deskripsi</Label><textarea name="description" :value="editing?.description??''" class="min-h-24 w-full rounded-md border bg-background p-3 text-sm"/></div><div class="flex justify-end gap-2 border-t pt-4"><Button type="button" variant="ghost" @click="close">Batal</Button><Button type="submit" :disabled="processing">{{editing?'Simpan perubahan':'Buat paket'}}</Button></div></Form></div></div></template>